  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'forecast',
      inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['location']}}},
    },
    async () => 'ok'
  );
  expect((await registry.execute('weather', {address: {}})).result).toContain('/address/location');
});
